 eye:vec4<f32>, sun:vec4<f32>, sunColor:vec4<f32>, ambient:vec4<f32>,
 viewport:vec4<f32>, viewDirection:vec4<f32>, options:vec4<f32>,
 // options.w enables the distant vista background.
