@group(0) @binding(0) var<uniform> frame:Frame;
fn toEye(world:vec3<f32>)->vec3<f32>{
 if(frame.viewDirection.w>.5){return normalize(frame.eye.xyz-world);}
 return frame.viewDirection.xyz;
}
@group(2) @binding(0) var shadowMap:texture_depth_2d;
fn visibility(world:vec3<f32>,n:vec3<f32>)->f32 {
 if(dot(n,frame.sun.xyz)<=.0001){return 0;}
 let p=frame.lightVP*vec4<f32>(world,1);let uv=p.xy*vec2<f32>(.5,-.5)+.5;
 if(any(uv<vec2<f32>(0))||any(uv>vec2<f32>(1))||p.z>1||p.z<0){return 1;}
 // Transform the receiver plane into orthographic light clip space. This uses
 // its actual geometric normal, including rotated parts, without derivatives.
 let m=frame.lightVP;
 let x=vec3<f32>(m[0].x,m[1].x,m[2].x);let y=vec3<f32>(m[0].y,m[1].y,m[2].y);let z=vec3<f32>(m[0].z,m[1].z,m[2].z);
 let plane=vec3<f32>(dot(n,x)/dot(x,x),dot(n,y)/dot(y,y),dot(n,z)/dot(z,z));
 let slope=vec2<f32>(-2*plane.x,2*plane.y)/plane.z;
 let size=vec2<f32>(textureDimensions(shadowMap));let texel=uv*size;let centre=vec2<i32>(floor(texel));
 var sum=0.0;var weightSum=0.0;
 for(var yOffset=-1;yOffset<=1;yOffset++){for(var xOffset=-1;xOffset<=1;xOffset++){
  let pixel=centre+vec2<i32>(xOffset,yOffset);let offset=vec2<f32>(pixel)+.5-texel;
  // A continuous 3x3 tent filter. Each depth is compared at its own texel centre,
  // so neighbours on a sloping face cannot incorrectly shadow that same face.
  let weights=max(vec2<f32>(0),vec2<f32>(1.5)-abs(offset));let weight=weights.x*weights.y;
  let receiver=p.z+dot(slope,offset/size)-.000004;
  var lit=1.0;
  if(all(pixel>=vec2<i32>(0))&&all(pixel<vec2<i32>(size))){lit=select(0.0,1.0,receiver<=textureLoad(shadowMap,pixel,0));}
  sum+=lit*weight;weightSum+=weight;
 }}return sum/weightSum;
}

struct ArcSegment { startRadius:vec4<f32>, endStrength:vec4<f32> };
struct ArcLight { colorRadius:vec4<f32>, strengthCount:vec4<f32>, segments:array<ArcSegment,8>, bounds:vec4<f32> };
struct ArcLights { count:vec4<f32>, lights:array<ArcLight> };
@group(2) @binding(2) var<storage,read> arcLights:ArcLights;
fn arcIllumination(world:vec3<f32>,normalOrView:vec3<f32>,mode:u32)->vec3<f32>{
 var result=vec3<f32>(0);
 for(var index=0u;index<min(u32(arcLights.count.x),min(arrayLength(&arcLights.lights),140u));index++){
  let bounds=arcLights.lights[index].bounds;let fromCentre=world-bounds.xyz;
  // Zero radius retains unbounded diagnostic records; production pools always
  // pack a conservative sphere enclosing every finite segment and falloff.
  if(bounds.w>0&&dot(fromCentre,fromCentre)>bounds.w*bounds.w){continue;}
  let light=arcLights.lights[index];var strongest=0.0;
  for(var segmentIndex=0u;segmentIndex<min(u32(light.strengthCount.y),8u);segmentIndex++){
   let segment=light.segments[segmentIndex];let axis=segment.endStrength.xyz-segment.startRadius.xyz;
   let t=clamp(dot(world-segment.startRadius.xyz,axis)/max(dot(axis,axis),.000001),0.0,1.0);
   let offset=segment.startRadius.xyz+axis*t-world;let d2=dot(offset,offset);
   let radius=light.colorRadius.w*segment.startRadius.w;let range2=radius*radius;
   if(range2>0&&d2<range2){
    let direction=offset*inverseSqrt(max(d2,.01));let cosine=dot(normalOrView,direction);
    var response=max(cosine,0.0);
    if(mode==1u){response=.28+.62*pow(max(-cosine,0.0),8)+.1*cosine*cosine;}
    if(mode==2u){response=abs(cosine);}
    let relative=d2/range2;let edge=1-relative;
    strongest=max(strongest,segment.endStrength.w*response*edge*edge/(1+relative*13.824));
   }
  }
  result+=light.colorRadius.rgb*(light.strengthCount.x*strongest);
 }return result;
}

struct ShotLight { positionRadius:vec4<f32>, colorStrength:vec4<f32> };
struct ShotLights { count:vec4<f32>, lights:array<ShotLight,77> };
@group(2) @binding(1) var<uniform> shotLights:ShotLights;
fn muzzleLighting(world:vec3<f32>,normal:vec3<f32>)->vec3<f32>{
 var result=vec3<f32>(0);
 for(var index=0u;index<min(u32(shotLights.count.x),77u);index++){
  let light=shotLights.lights[index];let offset=light.positionRadius.xyz-world;
  let d2=dot(offset,offset);let range2=light.positionRadius.w*light.positionRadius.w;
  if(d2<range2){
   let relativeD2=d2/range2;let edge=1-relativeD2;let diffuse=max(dot(normal,offset*inverseSqrt(max(d2,.01))),0);
   // Preserve the original 48-unit curve (48*48*.006 = 13.824), scaling
   // the entire falloff with radius rather than only extending its cutoff.
   result+=light.colorStrength.rgb*(light.colorStrength.w*diffuse*edge*edge/(1+relativeD2*13.824));
  }
 }return result+arcIllumination(world,normal,0u);
}
